    "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/",
    "page": "https://commons.wikimedia.org/wiki/File:Eight_Allotropes_of_Carbon.svg",
    "file": "Eight_Allotropes_of_Carbon.svg"
